        case "content":
          judgment.push(`[${f.id}] ${f.message} — content rewrite needed`);
          break;
      }
    } else if (!f.fixable) {
      judgment.push(`[${f.id}] ${f.message}`);
    }
  }

  return { mechanical, judgment };
}

