1→import { defineCommand } from "citty";
import { homedir } from "os";
import { resolve } from "path";
import { confirm, isCancel, select, multiselect } from "@clack/prompts";
import { applyRemove, listRemoveCandidates, planRemove, resolveSkillName, type SkillMatch } from "../../../core/skill-remove.js";
import { loadRecentSessions } from "../../../core/session-evidence.js";
import { canPromptInteractively } from "../fix.js";
import { isAgentCaller, refuseAgentWrite, shouldBlockAgentWrite } from "../../agent-detect.js";
import { ui, resolveOutputMode, outJson, emitError, summaryLine, nextAction } from "../../out.js";
10→import { exit } from "../../render/exit.js";

const AGENTS = new Set(["claude", "cursor", "copilot", "codex", "grok"]);

export default defineCommand({
  meta: {
    name: "remove",
    description: [
      "Delete an Authored Skill, or Quarantine a Global Skill",
      "",
20→      "Examples:",
      "  dora skill remove ghost --dry-run",
      "  dora skill remove ghost --yes",
      "  dora skill remove ghost --for claude --yes",
      "Exit: 0 clean · 1 issues · 2 could not run",
    ].join("\n"),
  },
  args: {
    name: { type: "positional", description: "Skill name or path", required: false },
    for: { type: "string", description: "Target agent: claude | cursor | codex | copilot | grok", alias: "f" },
30→    global: { type: "boolean", description: "Select a Global Skill when the name clashes", default: false },
    yes: { type: "boolean", description: "Delete without prompting", default: false, alias: "y" },
    "dry-run": { type: "boolean", description: "Show the plan, write nothing", default: false },
    format: { type: "string", description: "Output format: table | json", default: "table" },
    json: { type: "boolean", description: "Alias for --format json", default: false },
    ci: { type: "boolean", description: "Machine mode (implies --format json)", default: false },
    cwd: { type: "string", description: "Working directory override" },
  },
  async run({ args }) {
    const mode = resolveOutputMode({ format: args.format as string, ci: args.ci as boolean, json: args.json as boolean });
40→    const cwd = args.cwd ? resolve(args.cwd as string) : process.cwd();
    const dryRun = Boolean(args["dry-run"]);
    const yes = Boolean(args.yes);
    const name = ((args.name as string) || "").trim();

    if (shouldBlockAgentWrite({ agent: isAgentCaller(), yes, dryRun })) {
      refuseAgentWrite("dora skill remove --dry-run");
      await exit(2);
      return;
    }
50→
    if (!name) {
      try {
        const canPick = canPromptInteractively(false, false, mode.format) && !isAgentCaller();
        if (!canPick) {
          ui.fail("Pass a Skill name.");
          nextAction("dora skill remove <name>");
          await exit(2);
          return;
        }
60→        const candidates = listRemoveCandidates({ cwd, home: homedir(), loaded: loadRecentSessions(cwd) });
        if (candidates.length === 0) {
          summaryLine("No Remove candidates.");
          await exit(0);
          return;
        }
        const picked = await multiselect({
          message: "Remove candidates",
          options: candidates.map((m) => ({ value: m.dir, label: `${m.name}  ${m.dir}` })),
          required: false,
70→          output: process.stderr,
        });
        if (isCancel(picked) || (picked as string[]).length === 0) {
          summaryLine("Nothing removed.");
          await exit(0);
          return;
        }
        const interactive = canPromptInteractively(yes, dryRun, mode.format);
        if (interactive) {
          const ok = await confirm({
80→            message: `Remove ${(picked as string[]).length} Authored Skill(s)?`,
            initialValue: false,
            output: process.stderr,
          });
          if (isCancel(ok) || !ok) {
            summaryLine("Nothing removed.");
            await exit(0);
            return;
          }
        } else if (!yes && !dryRun) {
90→          ui.fail("Pass --yes to remove, or --dry-run to preview.");
          nextAction("dora skill remove --dry-run");
          await exit(2);
          return;
        }
        let n = 0;
        for (const dir of picked as string[]) {
          const resolved = resolveSkillName({ name: dir, cwd, home: homedir() });
          const plan = planRemove(resolved, cwd);
          if (!plan.ok) continue;
100→          if (!dryRun) applyRemove(plan);
          n++;
        }
        summaryLine(dryRun ? `Would remove ${n} Skill(s)` : `Removed ${n} Skill(s)`);
        await exit(0);
      } catch (e) {
        emitError(e, mode);
        await exit(2);
      }
      return;
110→    }

    const forRaw = args.for as string | undefined;
    if (forRaw && !AGENTS.has(forRaw)) {
      ui.fail(`Unknown agent: ${forRaw}`);
      nextAction("dora skill remove --for claude");
      await exit(1);
      return;
    }

120→    try {
      let resolved = resolveSkillName({
        name, cwd, home: homedir(), forAgent: forRaw, globalOnly: Boolean(args.global),
      });
      if (resolved.status === "ambiguous") {
        const hits = resolved.matches;
        const canPick = canPromptInteractively(false, false, mode.format) && !isAgentCaller();
        if (canPick) {
          const picked = await select({
            message: `Name "${name}" matches more than one Skill`,
130→            options: hits.map((m: SkillMatch) => ({
              value: m.dir,
              label: `${m.origin}${m.agent ? ` · ${m.agent}` : ""}  ${m.dir}`,
            })),
            output: process.stderr,
          });
          if (isCancel(picked) || !picked) {
            summaryLine("Nothing deleted.");
            await exit(0);
            return;
140→          }
          resolved = resolveSkillName({ name: String(picked), cwd, home: homedir() });
        } else {
          const list = hits.map((m) => `${m.origin}${m.agent ? `/${m.agent}` : ""} ${m.dir}`).join("; ");
          ui.fail(`Name "${name}" matches more than one Skill (${list}).`);
          nextAction(`dora skill remove ${name} --for <agent> | --global | <path>`);
          await exit(2);
          return;
        }
      }
150→      const plan = planRemove(resolved, cwd);

      if (!plan.ok) {
        if (plan.reason === "none") {
          ui.fail(`No Skill named "${name}".`);
          nextAction("dora skill remove");
          await exit(1);
          return;
        }
        if (plan.reason === "ambiguous") {
160→          const hits = resolved.status === "ambiguous" ? resolved.matches : [];
          const list = hits.map((m) => `${m.agent ?? m.origin} ${m.dir}`).join(", ");
          ui.fail(`Name "${name}" matches more than one Skill (${list}).`);
          nextAction(`dora skill remove ${name} --for <agent> | --global | <path>`);
          await exit(2);
          return;
        }
        if (plan.reason === "imported") {
          ui.fail(`Refusing to remove an Imported Skill (${resolved.status === "imported" ? resolved.match.dir : name}).`);
          nextAction("dora skill remove");
170→          await exit(1);
          return;
        }
        if (plan.reason === "plugin-owned") {
          ui.fail(`"${name}" is a Plugin-owned Skill.`);
          nextAction(`dora review --quick ${plan.pluginRoot}`);
          await exit(1);
          return;
        }
        ui.fail(`Cannot remove "${name}".`);
180→        nextAction("dora skill remove");
        await exit(1);
        return;
