tool_input.old_string:
/** Next for unused. Standalone Remove first. Never Review home. */
export function unusedNext(candidates: UnusedRow[]): string | undefined {
  const first = candidates.find((c) => c.removable && isStandaloneUnused(c))
    ?? candidates.find((c) => c.removable);
  if (first) return `dora skill remove ${first.name} --dry-run`;
  const plug = candidates.find((c) => (c.kind === "plugin" || !c.removable) && c.pluginRoot);
  if (plug?.pluginRoot) return `dora review --quick ${plug.pluginRoot}`;
}

tool_input.new_string:
/** Next for unused. Standalone Remove first. Plugin rows Review the root. Never Review home. */
export function unusedNext(candidates: UnusedRow[]): string | undefined {
  const first = candidates.find((c) => c.removable && isStandaloneUnused(c));
  if (first) return `dora skill remove ${first.name} --dry-run`;
  const plug = candidates.find((c) => c.pluginRoot);
  if (plug?.pluginRoot) return `dora review --quick ${plug.pluginRoot}`;
}

tool_input.old_string:
test("standalone Remove candidate wins; unused-recent is not Next", () => {
  expect(unusedNext([
    { name: "caveman", dir: "/plug/caveman", origin: "global", kind: "plugin", removable: false, pluginRoot: "/plug" },
    { name: "ghost", dir: "/home/.agents/skills/ghost", origin: "global", kind: "skill", removable: true },
  ])).toBe("dora skill remove ghost --dry-run");
  expect(unusedNext([])).toBeUndefined();
});

tool_input.new_string:
test("standalone Remove candidate wins; plugin-owned is Review; unused-recent is not Next", () => {
  expect(unusedNext([
    { name: "caveman", dir: "/plug/skills/caveman", origin: "global", kind: "skill", removable: true, pluginRoot: "/plug" },
    { name: "ghost", dir: "/home/.agents/skills/ghost", origin: "global", kind: "skill", removable: true },
  ])).toBe("dora skill remove ghost --dry-run");
  expect(unusedNext([
    { name: "caveman", dir: "/plug/skills/caveman", origin: "global", kind: "skill", removable: true, pluginRoot: "/plug" },
  ])).toBe("dora review --quick /plug");
  expect(unusedNext([])).toBeUndefined();
});

